<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'; import EmptyState from '../../Components/Feedback/EmptyState.vue'; import Pagination from '../../Components/Navigation/Pagination.vue'; import AppLayout from '../../Layouts/AppLayout.vue';
interface Row{id:number;order_number:string;email:string|null;financial_status:string|null;fulfillment_status:string|null;currency:string;total_price:string;items_count:number;created_at_shopify:string|null;synced_at:string|null} interface P<T>{data:T[];links:Array<{url:string|null;label:string;active:boolean}>} const props=defineProps<{orders:P<Row>;filters:{search?:string;financial_status?:string;fulfillment_status?:string}}>(); const form=useForm({search:props.filters.search??'',financial_status:props.filters.financial_status??'',fulfillment_status:props.filters.fulfillment_status??''}); const submit=()=>form.get('/orders',{preserveState:true,replace:true}); const date=(v:string|null)=>v?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
const financialStatus = (value:string|null) => ({paid:'已付款',pending:'待付款',authorized:'已授权',partially_paid:'部分付款',partially_refunded:'部分退款',refunded:'已退款',voided:'已作废'}[value ?? ''] ?? value ?? '未知');
const fulfillmentStatus = (value:string|null) => ({fulfilled:'已履约',partial:'部分履约',restocked:'已重新入库',unfulfilled:'未履约'}[value ?? ''] ?? value ?? '未履约');
const money = (value:string) => Number(value).toFixed(2);
</script>
<template><Head title="订单管理"/><AppLayout :breadcrumbs="[{label:'工作台',href:'/dashboard'},{label:'业务中心'},{label:'订单管理'}]"><div class="mx-auto max-w-7xl space-y-6"><header><p class="text-sm font-semibold text-emerald-700">Shopify 订单</p><h1 class="mt-1 text-3xl font-semibold text-slate-950">订单管理</h1><p class="mt-2 text-sm text-slate-500">查看当前店铺同步的订单、付款与履约状态。</p></header><form class="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm lg:grid-cols-[minmax(0,1fr)_190px_190px_auto]" @submit.prevent="submit"><input v-model="form.search" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm" placeholder="搜索订单号或客户邮箱"/><select v-model="form.financial_status" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm"><option value="">全部付款状态</option><option value="paid">已付款</option><option value="pending">待付款</option><option value="authorized">已授权</option><option value="partially_paid">部分付款</option><option value="refunded">已退款</option><option value="voided">已作废</option></select><select v-model="form.fulfillment_status" class="rounded-xl border border-slate-200 bg-slate-50 px-4 py-2.5 text-sm"><option value="">全部履约状态</option><option value="unfulfilled">未履约</option><option value="partial">部分履约</option><option value="fulfilled">已履约</option><option value="restocked">已重新入库</option></select><button class="rounded-xl bg-slate-950 px-5 py-2.5 text-sm font-semibold text-white">筛选</button></form><section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div v-if="orders.data.length" class="overflow-x-auto"><table class="w-full min-w-[940px] text-left text-sm"><thead class="border-b border-slate-200 bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-4">订单</th><th class="px-5 py-4">客户</th><th class="px-5 py-4">付款</th><th class="px-5 py-4">履约</th><th class="px-5 py-4">商品项</th><th class="px-5 py-4">金额</th><th class="px-5 py-4">下单时间</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="order in orders.data" :key="order.id" class="hover:bg-slate-50"><td class="px-5 py-4"><Link :href="`/orders/${order.id}`" class="font-semibold text-slate-950 hover:text-emerald-700">{{ order.order_number }}</Link></td><td class="px-5 py-4 text-slate-600">{{ order.email || '访客' }}</td><td class="px-5 py-4"><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700">{{ financialStatus(order.financial_status) }}</span></td><td class="px-5 py-4 text-slate-600">{{ fulfillmentStatus(order.fulfillment_status) }}</td><td class="px-5 py-4">{{ order.items_count }}</td><td class="px-5 py-4 font-semibold">{{ order.currency }} {{ money(order.total_price) }}</td><td class="px-5 py-4 text-xs text-slate-500">{{ date(order.created_at_shopify) }}</td></tr></tbody></table></div><EmptyState v-else class="border-0 shadow-none" title="暂无订单数据" description="创建订单同步任务后，Shopify 订单会显示在这里。" icon="orders"/></section><Pagination :links="orders.links"/></div></AppLayout></template>
